import { NavLink } from 'react-router';
import { useEffect, useId, useRef, useSyncExternalStore } from 'react';
import { useCliente } from '../cliente/ProveedorCliente.tsx';
import { IdGuionSchema } from '../cliente/demo.ts';

const sinCambios = () => () => {};
const sinPaso = () => null;

const canales = [
  { ruta: '/web', nombre: 'Web' },
  { ruta: '/wa', nombre: 'WhatsApp' },
  { ruta: '/app', nombre: 'App' },
  { ruta: '/callcenter', nombre: 'Call Center' },
  { ruta: '/clinica', nombre: 'Clínica' },
  { ruta: '/admin', nombre: 'Admin' },
  { ruta: '/bandeja', nombre: 'Bandeja' },
];

export function BarraDemo() {
  const barra = useRef<HTMLElement>(null);
  const idPaso = useId();
  useEffect(() => {
    if (!barra.current || typeof ResizeObserver === 'undefined') return;
    const actualizar = () => document.documentElement.style.setProperty('--alto-barra-demo', `${barra.current!.getBoundingClientRect().height}px`);
    const observador = new ResizeObserver(actualizar); observador.observe(barra.current); actualizar();
    return () => { observador.disconnect(); document.documentElement.style.removeProperty('--alto-barra-demo'); };
  }, []);
  const { demo } = useCliente();
  const paso = useSyncExternalStore(demo?.alCambiar ?? sinCambios, demo?.paso ?? sinPaso);
  return (
    <nav className="barra-demo" aria-label="Canales de la demo" ref={barra}>
      <ul>
        {canales.map(({ ruta, nombre }) => (
          <li key={ruta}><NavLink to={ruta}>{nombre}</NavLink></li>
        ))}
      </ul>
      {paso && (
        <div className="franja-simulacion">
          <div className="control-demo">
            <span className="etiqueta-simulacion">Simulación</span>
            <label>Guion de demo <select value={demo?.guion()} onChange={evento => demo?.elegirGuion(IdGuionSchema.parse(evento.target.value))}><option value="flujoA">Flujo A</option><option value="flujoC">Flujo C</option></select></label>
            <div className="avance-demo">
              <p id={idPaso} role="status">Paso {paso.numero} de {paso.total} · {paso.titulo}</p>
              <progress className="progreso-demo" value={paso.numero} max={paso.total} aria-labelledby={idPaso} />
            </div>
            <button type="button" onClick={() => demo?.reiniciar()}>Reiniciar guion</button>
          </div>
        </div>
      )}
    </nav>
  );
}

import { useEffect, useRef } from 'react';
import { Link, Outlet, useLocation } from 'react-router';
import { BarraDemo } from './BarraDemo.tsx';
import { useCliente } from '../cliente/ProveedorCliente.tsx';

export function Layout() {
  const { pathname } = useLocation();
  const cliente = useCliente();
  const contenido = useRef<HTMLElement>(null);

  useEffect(() => {
    contenido.current?.focus();
  }, [pathname]);

  return (
    <div className="layout min-h-dvh flex flex-col">
      <a className="saltar-contenido" href="#contenido">Saltar al contenido</a>
      <header className="cabecera flex items-center justify-between gap-6">
        <Link className="marca" to="/" aria-label="Salud Digna 360 · Portada">Salud Digna 360</Link>
        <div className="contexto">HackaTec{cliente.modo === 'mock' && <span className="insignia-mock">Modo simulado</span>}</div>
      </header>
      <BarraDemo />
      <main className="contenido flex-1" id="contenido" ref={contenido} tabIndex={-1}>
        <Outlet />
      </main>
      <footer className="pie flex flex-wrap justify-between gap-3">
        <span>Base en desarrollo</span><span>Entorno de demostración · Datos ficticios</span>
      </footer>
    </div>
  );
}

import type { EventoVista } from '@noki/contracts';
import { fechaEnSede } from './formato.ts';

export const NOMBRES_CANAL: Record<EventoVista['canal'], string> = { web: 'Web', whatsapp: 'WhatsApp', app: 'App', callcenter: 'Call Center', clinica: 'Clínica' };

export function LineaTiempo({ eventos }: { eventos: EventoVista[] }) {
  return (
    <section className="seccion" aria-labelledby="titulo-linea-tiempo">
      <h2 id="titulo-linea-tiempo">Línea de tiempo</h2>
      {eventos.length === 0 ? <p>Aún no hay eventos en este hilo.</p> : (
        <ol className="linea-tiempo" aria-label="Eventos del hilo">
          {eventos.map(evento => <li key={evento.id}>
            <strong>{evento.tipo}</strong><span>{NOMBRES_CANAL[evento.canal]}</span>
            <time dateTime={evento.ts}>{fechaEnSede(evento.ts, 'UTC')} UTC</time>
          </li>)}
        </ol>
      )}
    </section>
  );
}

import { EstadoCarga } from './EstadoCarga.tsx';
import { EstadoError } from './EstadoError.tsx';

export function EstadoContexto({ contexto, texto }: {
  contexto: { cargando: boolean; error: unknown; actualizar: () => void }; texto: string;
}) {
  if (contexto.cargando) return <EstadoCarga texto="Consultando el contexto de atención…" />;
  if (contexto.error) return <EstadoError error={contexto.error} onReintentar={contexto.actualizar} />;
  return <div className="seccion"><p>{texto}</p><button type="button" onClick={contexto.actualizar}>Actualizar</button></div>;
}

import { CanalSchema } from '@noki/contracts';
import { Link } from 'react-router';

const nombres = {
  web: 'Web', whatsapp: 'WhatsApp', app: 'App',
  callcenter: 'Call Center', clinica: 'Clínica',
} satisfies Record<(typeof CanalSchema.options)[number], string>;

const rutas = {
  web: '/web', whatsapp: '/wa', app: '/app',
  callcenter: '/callcenter', clinica: '/clinica',
} satisfies Record<(typeof CanalSchema.options)[number], string>;

export function Portada() {
  return (
    <>
      <h1>Un mismo hilo,<br /> en cada canal.</h1>
      <p className="introduccion">Una base compartida para que la atención continúe de un canal a otro, sin volver a empezar.</p>
      <section className="canales" aria-labelledby="titulo-canales">
        <h2 id="titulo-canales">Canales de atención</h2>
        <ul className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5">
          {CanalSchema.options.map(canal => <li key={canal}><Link to={rutas[canal]}>{nombres[canal]}</Link></li>)}
        </ul>
      </section>
      <p className="alcance">Los simuladores de atención estarán disponibles en próximas entregas.</p>
    </>
  );
}

import { useCliente, useConsulta, useContextoConsulta } from '../cliente/ProveedorCliente.tsx';
import { EstadoCarga } from '../componentes/EstadoCarga.tsx';
import { EstadoError } from '../componentes/EstadoError.tsx';
import { LineaTiempo, NOMBRES_CANAL } from '../componentes/LineaTiempo.tsx';
import { EstadoContexto } from '../componentes/EstadoContexto.tsx';
import { useSala } from '../cliente/useSala.ts';
import { RelojDemo } from '../componentes/RelojDemo.tsx';
import type { HuecoVista } from '@noki/contracts';
import { fechaEnSede } from '../componentes/formato.ts';

const ETIQUETAS_KPI: Record<string, string> = {
  cambiosCanal: 'Cambios de canal', cambiosCanalPorHilo: 'Cambios de canal por hilo',
  tramitesRecuperados: 'Trámites recuperados', citasConfirmadas: 'Citas confirmadas',
  llegadasRegistradas: 'Llegadas registradas', datosRepetidos: 'Datos repetidos',
  intentosVerificacionFallidos: 'Intentos de verificación fallidos',
  huecosLiberados: 'Huecos liberados', huecosRecuperados: 'Huecos recuperados',
  horasRecursoRecuperadas: 'Horas de recurso recuperadas', diasAdelantadosPromedio: 'Días adelantados en promedio',
};
const ESTADOS_HUECO: Record<HuecoVista['estado'], string> = { DETECTADO: 'Detectado', OFRECIDO: 'Ofrecido', ASIGNADO: 'Asignado', DESIERTO: 'Desierto' };
const ESTADOS_OFERTA: Record<HuecoVista['ofertas'][number]['estado'], string> = { OFRECIDA: 'Ofrecida', ACEPTADA: 'Aceptada', RECHAZADA: 'Rechazada', EXPIRADA: 'Expirada', PERDIDA: 'Perdida' };
const formatoNumero = new Intl.NumberFormat('es-MX', { maximumSignificantDigits: 21 });
const formatoHora = new Intl.DateTimeFormat('es-MX', { dateStyle: 'short', timeStyle: 'short' });

export function Admin() {
  const cliente = useCliente();
  const metricas = useConsulta('metricas', {});
  const alertas = useConsulta('alertasSeguridad', {});
  const huecos = useConsulta('panelHuecos', {});
  const contexto = useContextoConsulta();
  const { hiloId } = contexto;
  useSala('admin');
  useSala(hiloId ? `hilo:${hiloId}` : undefined);
  const ficha = useConsulta('fichaHilo', hiloId ? { hiloId } : undefined);
  return <>
    <h1>Administración</h1><p className="introduccion">El mismo hilo, con la trazabilidad de cada canal.</p>
    {metricas.isPending && <EstadoCarga />}
    {metricas.isError && <EstadoError error={metricas.error} onReintentar={() => { void metricas.refetch(); }} />}
    {metricas.data && <>
      <section className="seccion"><h2>Trámites por estado</h2><dl className="datos">{metricas.data.porEstado.map(fila => <div key={fila.estado}><dt>{fila.estado}</dt><dd>{fila.cantidad}</dd></div>)}</dl></section>
      <section className="seccion"><h2>Indicadores disponibles</h2><dl className="datos">{Object.entries(metricas.data.kpis).map(([nombre, valor]) => <div key={nombre}><dt>{Object.hasOwn(ETIQUETAS_KPI, nombre) ? ETIQUETAS_KPI[nombre] : nombre}</dt><dd>{formatoNumero.format(valor)}</dd></div>)}</dl></section>
    </>}
    <section className="seccion" aria-labelledby="titulo-huecos">
      <h2 id="titulo-huecos">Panel de huecos</h2>
      {huecos.isPending && <EstadoCarga texto="Cargando huecos…" />}
      {huecos.isError && <EstadoError error={huecos.error} onReintentar={() => { void huecos.refetch(); }} />}
      {huecos.data?.length === 0 && <p>No hay huecos liberados.</p>}
      {huecos.data && huecos.data.length > 0 && <ol className="panel-huecos" aria-label="Huecos liberados">{huecos.data.map(hueco => <li key={hueco.id}>
        <h3>{hueco.servicio}</h3>
        <dl className="datos">
          <div><dt>Sede</dt><dd>{hueco.sede}</dd></div>
          <div><dt>Fecha y hora en la sede</dt><dd><time dateTime={hueco.inicio}>{fechaEnSede(hueco.inicio, hueco.zonaHoraria)}</time><small>{hueco.zonaHoraria}</small></dd></div>
          <div><dt>Estado del hueco</dt><dd>{ESTADOS_HUECO[hueco.estado]}</dd></div>
        </dl>
        <ol className="ofertas-hueco" aria-label={`Ofertas de ${hueco.servicio}`}>{hueco.ofertas.map((oferta, indice) => <li key={indice}>
          <strong>{ESTADOS_OFERTA[oferta.estado]}</strong>
          <dl className="datos"><div><dt>Envío</dt><dd><time dateTime={oferta.enviadaEn}>{formatoHora.format(new Date(oferta.enviadaEn))}</time></dd></div>
            <div><dt>Vencimiento</dt><dd><time dateTime={oferta.expiraEn}>{formatoHora.format(new Date(oferta.expiraEn))}</time></dd></div></dl>
        </li>)}</ol>
      </li>)}</ol>}
    </section>
    <section className="seccion" aria-labelledby="titulo-alertas">
      <h2 id="titulo-alertas">Alertas de seguridad</h2>
      {alertas.isPending && <EstadoCarga texto="Cargando alertas de seguridad…" />}
      {alertas.isError && <EstadoError error={alertas.error} onReintentar={() => { void alertas.refetch(); }} />}
      {alertas.data?.length === 0 && <p>Sin alertas de seguridad</p>}
      {alertas.data && alertas.data.length > 0 && <ol className="linea-tiempo" aria-label="Alertas de seguridad">
        {alertas.data.map(alerta => <li key={alerta.id}>
          <strong>{NOMBRES_CANAL[alerta.canal]}</strong>
          <span>{alerta.intentos} {alerta.intentos === 1 ? 'intento' : 'intentos'}{alerta.bloqueado && <> · <strong>Bloqueado</strong></>}</span>
          <time dateTime={alerta.ts}>{formatoHora.format(new Date(alerta.ts))}</time>
        </li>)}
      </ol>}
    </section>
    {!hiloId && <EstadoContexto contexto={contexto} texto="Aún no hay un hilo que mostrar. Inicia la atención o confirma una cita y vuelve a actualizar." />}
    {hiloId && ficha.isPending && <EstadoCarga texto="Cargando el hilo…" />}
    {ficha.isError && <EstadoError error={ficha.error} onReintentar={() => { void ficha.refetch(); }} />}
    {ficha.data && <LineaTiempo eventos={ficha.data.lineaTiempo} />}
    {cliente.relojDemo && <RelojDemo reloj={cliente.relojDemo} />}
  </>;
}

import { Link } from 'react-router';
import { useState } from 'react';
import type { CitaVista } from '@noki/contracts';
import { useConsulta, useContextoConsulta } from '../cliente/ProveedorCliente.tsx';
import { EstadoCarga } from '../componentes/EstadoCarga.tsx';
import { EstadoError } from '../componentes/EstadoError.tsx';
import { QrCita } from '../componentes/QrCita.tsx';
import { fechaEnSede } from '../componentes/formato.ts';
import { EstadoContexto } from '../componentes/EstadoContexto.tsx';
import { useSala } from '../cliente/useSala.ts';
import { useAccion } from '../cliente/useAccion.ts';
import { ErrorCliente } from '../cliente/errores.ts';

function CancelacionCita({ cita }: { cita: CitaVista }) {
  const [confirmando, confirmar] = useState(false);
  const accion = useAccion();
  const pendiente = accion.error instanceof ErrorCliente && accion.error.codigo === 'STEP_UP_REQUERIDO';
  const cancelada = cita.tramite.estado === 'CANCELADA' || accion.data?.tramite.estado === 'CANCELADA';
  return <div>
    {cita.tramite.estado === 'CONFIRMADA' && (!confirmando || pendiente) && !accion.data && <button type="button" className="boton-secundario" onClick={() => { accion.reset(); confirmar(true); }}>Cancelar cita</button>}
    {confirmando && !accion.isSuccess && !pendiente && !cancelada && <div>
      <p>¿Quieres cancelar esta cita?</p>
      <button type="button" disabled={accion.isPending || accion.isError} onClick={() => accion.ejecutar({ tipo: 'comando', titulo: 'Cancelar cita', comando: { tipo: 'CancelarCita', canal: 'app', actor: 'paciente', tramiteId: cita.tramite.id, payload: {} } })}>Confirmar cancelación</button>
      <button type="button" className="boton-secundario" disabled={accion.isPending} onClick={() => { confirmar(false); accion.reset(); }}>Conservar cita</button>
    </div>}
    {accion.isPending && <EstadoCarga texto="Solicitando cancelación…" />}
    {accion.isError && !pendiente && <EstadoError error={accion.error} onReintentar={accion.reintentar} />}
    {cancelada && <p role="status">La cita se canceló.</p>}
    {pendiente && !cancelada && <div><p role="status">La cancelación espera aprobación en WhatsApp.</p><Link className="enlace-principal" to="/wa">Abrir WhatsApp</Link></div>}
  </div>;
}

export function App() {
  const contexto = useContextoConsulta();
  const { pacienteId } = contexto;
  useSala(pacienteId ? `paciente:${pacienteId}` : undefined);
  const citas = useConsulta('citasPaciente', pacienteId ? { pacienteId } : undefined);
  return <>
    <h1>App</h1><p className="introduccion">Tus citas y el QR para continuar en clínica.</p>
    {!pacienteId && <EstadoContexto contexto={contexto} texto="Aún no hay un paciente en el contexto de atención. Confirma una cita y vuelve a actualizar para ver tus citas." />}
    {pacienteId && citas.isPending && <EstadoCarga />}
    {citas.isError && <EstadoError error={citas.error} onReintentar={() => { void citas.refetch(); }} />}
    {citas.data?.length === 0 && <div className="seccion"><p>Aún no hay citas para mostrar.</p><Link className="enlace-principal" to="/callcenter">Iniciar atención en Call Center</Link></div>}
    {citas.data?.map(cita => <section className="seccion cita" key={cita.tramite.id} aria-label="Cita del paciente">
      <div><h2>{cita.servicio}</h2><dl className="datos">
        <div><dt>Estado</dt><dd>{cita.tramite.estado}</dd></div><div><dt>Sede</dt><dd>{cita.sede}</dd></div>
        <div><dt>Fecha y hora en la sede</dt><dd><time dateTime={cita.inicio}>{fechaEnSede(cita.inicio, cita.zonaHoraria)}</time><small>{cita.zonaHoraria}</small></dd></div>
      </dl><p>Presenta este QR en recepción.</p><CancelacionCita cita={cita} /></div><QrCita token={cita.tokenQr} />
    </section>)}
  </>;
}

import { useConsulta, useContextoConsulta } from '../cliente/ProveedorCliente.tsx';
import { EstadoCarga } from '../componentes/EstadoCarga.tsx';
import { EstadoError } from '../componentes/EstadoError.tsx';
import { LlegadaClinica } from '../componentes/LlegadaClinica.tsx';
import { EstadoContexto } from '../componentes/EstadoContexto.tsx';
import { useSala } from '../cliente/useSala.ts';

export function Clinica() {
  const contexto = useContextoConsulta();
  const { sedeId } = contexto;
  useSala(sedeId ? `sede:${sedeId}` : undefined);
  const llegadas = useConsulta('llegadasSede', sedeId ? { sedeId } : undefined);
  return <>
    <h1>Clínica</h1><p className="introduccion">Recepción · Llegadas esperadas</p>
    {!sedeId && <EstadoContexto contexto={contexto} texto="Aún no hay llegadas que mostrar: falta la sede de atención. Confirma una cita y vuelve a actualizar." />}
    {sedeId && llegadas.isPending && <EstadoCarga />}
    {llegadas.isError && <EstadoError error={llegadas.error} onReintentar={() => { void llegadas.refetch(); }} />}
    {llegadas.data?.length === 0 && <p className="seccion">Aún no hay llegadas esperadas. Confirma una cita en WhatsApp.</p>}
    {llegadas.data?.map(llegada => <LlegadaClinica key={llegada.cita.tramite.id} llegada={llegada} />)}
  </>;
}

import { useConsulta } from '../cliente/ProveedorCliente.tsx';
import { EstadoCarga } from '../componentes/EstadoCarga.tsx';
import { EstadoError } from '../componentes/EstadoError.tsx';

export function Bandeja() {
  const mensajes = useConsulta('bandeja', {});
  return <>
    <h1>Bandeja simulada</h1><p className="introduccion">SMS y correos ficticios de la demo. Los códigos se muestran solo aquí.</p>
    {mensajes.isPending && <EstadoCarga />}
    {mensajes.isError && <EstadoError error={mensajes.error} onReintentar={() => { void mensajes.refetch(); }} />}
    {mensajes.data?.length === 0 && <p className="seccion">No hay mensajes simulados todavía.</p>}
    {mensajes.data?.map(mensaje => <article className="seccion" key={mensaje.id}><h2>{mensaje.asunto}</h2><p className="canal-mensaje">{mensaje.canal === 'sms' ? 'SMS' : 'Correo'}</p><p>{mensaje.cuerpo}</p></article>)}
  </>;
}

