.saltar-contenido:focus { transform: translateY(0); }
.contenido:focus { outline: none; }
.franja-simulacion { background: var(--sd-fondo-suave); }
.control-demo { display: grid; grid-template-columns: auto auto minmax(0, 1fr) auto; align-items: center; gap: 0.75rem 1rem; width: min(100% - 3rem, 72rem); margin: 0 auto; padding-block: 0.75rem; }
.etiqueta-simulacion { justify-self: start; color: var(--tinta); font-size: 0.75rem; font-weight: 700; text-transform: uppercase; }
.avance-demo { min-width: 0; }
.control-demo p { margin: 0; font-size: 0.8125rem; color: var(--tinta-secundaria); }
.progreso-demo { display: block; box-sizing: border-box; appearance: none; width: 100%; height: 0.625rem; margin-top: 0.375rem; overflow: hidden; border: 1px solid var(--borde-control); border-radius: 0.5rem; background: var(--linea); }
.progreso-demo::-webkit-progress-bar { background: var(--linea); }
.progreso-demo::-webkit-progress-value { background: var(--sd-marca); }
.progreso-demo::-moz-progress-bar { background: var(--sd-marca); }
button, input { font: inherit; }
button { display: inline-flex; align-items: center; justify-content: center; min-width: 44px; min-height: 44px; padding: 0.625rem 1rem; border: 1px solid var(--sd-accion); border-radius: 0.5rem; background: var(--sd-accion); color: var(--sd-fondo); line-height: 1.4; cursor: pointer; }
button:hover:enabled { background: var(--sd-accion-hover); }
button:disabled { background: var(--fondo-deshabilitado); color: var(--tinta-secundaria); border-color: var(--borde-control); cursor: default; }
.control-demo button { justify-self: end; background: transparent; color: var(--tinta); border-color: var(--borde-control); font-size: 0.8125rem; }
.control-demo button:hover:enabled { background: var(--sd-fondo-interactivo); }
.control-demo label { display: flex; align-items: center; flex-wrap: wrap; gap: 0.5rem; font-size: 0.8125rem; }
.control-demo select { min-height: 44px; max-width: 100%; padding: 0.5rem; border: 1px solid var(--borde-control); border-radius: 0.5rem; color: inherit; background: var(--sd-fondo-suave); font: inherit; }
.panel-huecos, .ofertas-hueco { margin: 0; padding: 0; list-style: none; }
.panel-huecos > li { padding-block: 1.5rem; border-bottom: 1px solid var(--linea); }
.panel-huecos h3 { margin-top: 0; }
.ofertas-hueco > li { padding-block: 0.75rem; border-top: 1px solid var(--linea); }
.ofertas-hueco .datos { margin-block: 0.75rem 0; }
.panel-huecos time { font-variant-numeric: tabular-nums; }
.seccion { margin-top: 2.5rem; padding-top: 1.5rem; border-top: 1px solid var(--linea); }
.seccion p, .mensaje-bot p, .estado-error p { max-width: 65ch; line-height: 1.65; margin-block: 0.5rem 1rem; }
.seccion h2 { font-size: 1.25rem; line-height: 1.4; }
h3 { margin: 0.75rem 0 0.5rem; font-size: 1rem; font-weight: 600; }
.acciones { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-block: 1rem; }
.reloj-demo-formulario label { display: block; font-weight: 600; }
.reloj-demo-formulario input { box-sizing: border-box; width: min(100%, 12rem); min-height: 44px; padding: 0.625rem 0.75rem; border: 1px solid var(--borde-control); border-radius: 0.5rem; color: inherit; background: var(--sd-fondo); caret-color: var(--sd-accion); }
.reloj-demo-formulario input[aria-invalid="true"] { border-color: var(--error); }
.reloj-demo time { overflow-wrap: anywhere; font-variant-numeric: tabular-nums; }
.llamada-entrante { max-width: 30rem; }
.llamada-entrante label { display: block; margin-bottom: 0.5rem; font-weight: 600; }
.llamada-entrante input { box-sizing: border-box; width: 100%; min-height: 44px; padding: 0.625rem 0.75rem; border: 1px solid var(--borde-control); border-radius: 0.5rem; color: inherit; background: var(--sd-fondo); caret-color: var(--sd-accion); }
.llamada-entrante input[aria-invalid="true"] { border-color: var(--error); }
.ayuda-ani { color: var(--tinta-secundaria); }
.consentimiento { display: flex; align-items: center; gap: 0.75rem; min-height: 44px; max-width: 46ch; margin-block: 1.5rem 0.75rem; line-height: 1.5; cursor: pointer; }
.consentimiento input { flex-shrink: 0; width: 24px; height: 24px; margin: 10px; accent-color: var(--sd-accion); }
.datos { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr)); gap: 1.5rem; margin-block: 1.5rem; }
.datos div { min-width: 0; }
.datos dt { margin-bottom: 0.375rem; color: var(--tinta-secundaria); font-size: 0.875rem; overflow-wrap: anywhere; }
.datos dd { margin: 0; font-size: 1.125rem; line-height: 1.5; overflow-wrap: anywhere; }
small { display: block; margin-top: 0.25rem; font-size: 0.8125rem; color: var(--tinta-secundaria); }
.aviso, .estado-error, .estado-carga { margin-block: 1rem; padding: 1rem; background: var(--sd-fondo-suave); line-height: 1.6; }
.estado-error { background: var(--fondo-error); color: var(--error); }
.linea-tiempo { margin: 0; padding: 0; list-style: none; }
.linea-tiempo li { display: grid; grid-template-columns: minmax(0, 1fr) auto; column-gap: 1rem; padding-block: 1rem; border-bottom: 1px solid var(--linea); overflow-wrap: anywhere; }
.linea-tiempo time { grid-column: 1 / -1; margin-top: 0.375rem; color: var(--tinta-secundaria); font-size: 0.8125rem; }
.conversacion { max-width: 44rem; margin-top: 2rem; }
.mensaje-bot { padding-block: 1rem; border-bottom: 1px solid var(--linea); }
.seccion-lista ul { display: grid; gap: 0.5rem; padding: 0; margin: 0; list-style: none; }
.seccion-lista button { width: 100%; justify-content: flex-start; background: transparent; color: var(--tinta); border-color: var(--borde-control); }
.seccion-lista button:hover:enabled { background: var(--sd-fondo-interactivo); }
.enviar-mensaje { margin-top: 2rem; }
.enviar-mensaje label { display: block; margin-bottom: 0.5rem; font-weight: 600; }
.enviar-mensaje > div { display: flex; gap: 0.5rem; }
.enviar-mensaje input { min-width: 0; width: 100%; min-height: 44px; padding-inline: 0.75rem; border: 1px solid var(--borde-control); border-radius: 0.5rem; background: var(--sd-fondo); color: var(--tinta); caret-color: var(--sd-accion); }
.enviar-mensaje input::placeholder { color: var(--tinta-secundaria); }
.cita { display: flex; align-items: flex-start; justify-content: space-between; flex-wrap: wrap; gap: 2rem; }
.cita > div:first-child { flex: 1 1 20rem; min-width: 0; }
.qr-cita { max-width: 100%; }
.qr-cita svg { display: block; width: min(224px, 100%); height: auto; }
.precio { font-size: 1.5rem; font-weight: 600; }
.continuacion { margin-top: 1.5rem; max-width: 100%; }
.continuacion code { display: block; overflow-wrap: anywhere; padding-block: 0.5rem; }
.canal-mensaje { font-weight: 600; color: var(--tinta-secundaria); }
.insignia-mock { display: block; width: fit-content; margin: 0.35rem 0 0 auto; padding: 0.2rem 0.5rem; border: 1px solid var(--linea); border-radius: 0.25rem; color: var(--tinta); font-size: 0.75rem; font-weight: 600; background: var(--sd-fondo-interactivo); }
.wa-simulador { max-width: 44rem; margin-inline: auto; }
.contenido:has(.wa-simulador) { padding-block: 2rem; }
.wa-simulador h1 { font-size: 2rem; }
.wa-simulador .introduccion { margin-top: 0.75rem; font-size: 1rem; }
.wa-herramientas { display: flex; align-items: end; flex-wrap: wrap; gap: 0.75rem; margin-block: 1.5rem; }
.wa-herramientas > div { flex: 1 1 12rem; min-width: 0; }
.wa-herramientas label { display: block; margin-bottom: 0.375rem; font-size: 0.875rem; font-weight: 600; }
.wa-herramientas input, .dialogo-wa input { box-sizing: border-box; width: 100%; min-height: 44px; border: 1px solid var(--borde-control); border-radius: 0.5rem; padding: 0.625rem 0.75rem; background: var(--sd-fondo); color: var(--tinta); font: inherit; }
.boton-secundario { color: var(--tinta); background: transparent; border-color: var(--borde-control); }
.boton-secundario:hover:enabled { color: var(--tinta); background: var(--sd-fondo-interactivo); }
.wa-historial { display: flex; flex-direction: column; align-items: flex-start; gap: 0.75rem; max-height: 52dvh; min-height: 16rem; overflow-y: auto; padding: 1rem; background: var(--sd-fondo-suave); border-radius: 0.75rem; scrollbar-color: var(--sd-accion) var(--sd-fondo-suave); scroll-padding-block: 1rem; }
.wa-vacio { align-self: center; max-width: 28rem; padding-block: 3rem; color: var(--tinta-secundaria); line-height: 1.65; }
.wa-burbuja { max-width: 90%; padding: 0.75rem 1rem; border-radius: 0.75rem; overflow-wrap: anywhere; line-height: 1.6; }
.wa-bot { background: var(--sd-fondo); }
.wa-usuario { align-self: flex-end; background: var(--sd-fondo-interactivo); }
.wa-burbuja p { margin: 0 0 0.5rem; }
.wa-burbuja p:last-child { margin-bottom: 0; }
.wa-burbuja .mensaje-bot { padding: 0; border: 0; }
.wa-burbuja .acciones { margin-bottom: 0; }
.wa-error { color: var(--error); line-height: 1.6; }
.wa-error button { margin-top: 0.5rem; }
.wa-escribiendo { color: var(--tinta-secundaria); margin: 0; font-size: 0.875rem; }
.wa-compositor { margin-top: 1rem; background: var(--sd-fondo); }
.dialogo-wa { width: min(32rem, calc(100% - 2rem)); max-height: calc(100dvh - 2rem); margin: auto; box-sizing: border-box; border: 0; border-radius: 0.75rem; padding: 1.5rem; background: var(--sd-fondo); color: var(--tinta); overflow-y: auto; }
.dialogo-wa::backdrop { background: var(--fondo-modal); }
.dialogo-wa header { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-bottom: 1.5rem; }
.dialogo-wa h2 { margin: 0; font-size: 1.25rem; line-height: 1.4; overflow-wrap: anywhere; }
.dialogo-wa .seccion-lista { margin-bottom: 1rem; }
.ayuda-flow { color: var(--tinta-secundaria); font-size: 0.9375rem; line-height: 1.6; margin-block: 1rem 1.5rem; }
.campo-flow { margin-block: 1.25rem; }
.campo-flow label { display: block; font-weight: 600; margin-bottom: 0.5rem; }
.captura-flow { display: flex; align-items: center; gap: 0.5rem; }
.captura-flow input { min-width: 0; }
.campo-flow input[aria-invalid="true"] { border-color: var(--error); }
.campo-flow .wa-error { margin: 0.5rem 0 0; font-size: 0.875rem; }
@media (max-width: 767px) {
  .layout { padding-bottom: var(--alto-barra-demo, calc(12rem + env(safe-area-inset-bottom))); }
  .barra-demo { position: fixed; inset: auto 0 0; padding-bottom: env(safe-area-inset-bottom); border-top: 1px solid var(--linea); border-bottom: 0; }
  .barra-demo ul { box-sizing: border-box; flex-wrap: nowrap; width: 100%; padding-inline: 0.5rem; overflow-x: auto; overscroll-behavior-x: contain; scroll-padding-inline: 0.5rem; scrollbar-width: thin; scrollbar-color: var(--sd-accion) var(--fondo-deshabilitado); }
  .barra-demo li { flex: 0 0 auto; }
  .barra-demo a { white-space: nowrap; font-size: 0.875rem; }
  .control-demo { grid-template-columns: minmax(0, 1fr) auto; width: calc(100% - 2rem); gap: 0.75rem; }
  .control-demo label { justify-self: end; }
  .cita > .qr-cita { order: -1; }
  .wa-simulador { padding-bottom: 6rem; }
  .wa-compositor { position: fixed; z-index: 9; inset: auto 1rem var(--alto-barra-demo, calc(12rem + env(safe-area-inset-bottom))) 1rem; max-width: 44rem; margin: 0 auto; padding-block: 0.75rem; }
  .wa-compositor label { font-size: 0.875rem; margin-bottom: 0.25rem; }
  .wa-historial { max-height: 48dvh; }
}
@media (max-width: 400px) {
  .cabecera, .contenido, .pie { width: calc(100% - 2rem); }
  .contexto { max-width: 12ch; }
}

raizCSS:
:root {
  color-scheme: light;
  font-family: "Open Sans", system-ui, sans-serif;
  color: var(--tinta);
  background: var(--sd-fondo);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --sd-marca: #008959;
  --sd-accion: #0074D9;
  --sd-accion-hover: #0066BF;
  --sd-enlace: #005BB5;
  --sd-fondo: #FFFFFF;
  --sd-fondo-suave: #ECF3F9;
  --sd-fondo-interactivo: #E6F2FC;
  --tinta: #2E3133;
  --tinta-secundaria: #43474A;
  --borde-control: #868589;
  --linea: #EEF0F2;
  --error: #763a23;
  --fondo-error: #f5e8df;
  --fondo-deshabilitado: #EEF0F2;
  --fondo-modal: rgb(10 35 26 / 55%);
}
